"""Randomised check: exported image equals brute-force language semantics."""
import itertools, json, random, sys
sys.path.insert(0,'/workspace/project'); sys.path.insert(0,'/workspace/tmp/t')
from syntax import parse_policy, PolicyError
from compiler.compiler import compile_policy, CompileError

D = 4294967295
rng = random.Random(20240513)

def rand_path(names, maxlen):
    n = rng.randint(0, maxlen)
    return [rng.choice(names) for _ in range(n)]

def rand_atom(names):
    op = rng.choice(['match','startswith','endswith','contains'])
    return ('atom', op, tuple(rand_path(names, 4 if op != 'match' else 3)))

def rand_pred(names, depth=1):
    if depth >= 3 or rng.random() < 0.45:
        return rand_atom(names)
    kind = rng.choice(['and','or','not'])
    if kind == 'not':
        return ('n', rand_pred(names, depth+1))
    return ('b', kind, rand_pred(names, depth+1), rand_pred(names, depth+1))

def rand_policy(names):
    rules = []
    for _ in range(rng.randint(0, 5)):
        if rng.random() < 0.4:
            tree = ('atom', 'match', tuple(rand_path(names, 3)))
        else:
            tree = rand_pred(names)
        rules.append((tree, rng.random() < 0.6))
    return rules

def matches(tree, seq):
    kind = tree[0]
    if kind == 'atom':
        op, path = tree[1], list(tree[2])
        m = len(path)
        if op == 'match':
            return seq == path
        if op == 'startswith':
            return seq[:m] == path
        if op == 'endswith':
            return seq[len(seq)-m:] == path if m else True
        return any(seq[i:i+m] == path for i in range(len(seq)-m+1))
    if kind == 'n':
        return not matches(tree[1], seq)
    left = matches(tree[2], seq); right = matches(tree[3], seq)
    return (left and right) if tree[1] == 'and' else (left or right)

def allowed(rules, seq):
    yes = any(flag and matches(tree, seq) for tree, flag in rules)
    no = any((not flag) and matches(tree, seq) for tree, flag in rules)
    return yes and not no

def image_run(image, columns, seq):
    state = 0
    for name in seq:
        target = image['rows'][state][columns[name]]
        if target == D:
            return False
        state = target
    return image['accept'][state]

def check_image(rules, names, labels):
    order = [n for _, n in sorted(zip(labels, names))]
    columns = {n: i for i, n in enumerate(order)}
    pol = ''.join('%s %s;' % (render(t), 'allow' if f else 'drop') for t, f in rules)
    rules2, atoms, paths = parse_policy(pol)
    accept, rows, cells = compile_policy(rules2, order, columns)
    image = {'accept': accept, 'rows': rows}
    n = len(rows)
    assert n <= 8192
    assert len(accept) == n
    for row in rows:
        assert len(row) == len(order)
        for t in row:
            assert t == D or 0 <= t < n
    # minimality over coaccessible machine: no duplicate (accept,row)
    sigs = set()
    for i in range(n):
        s = (accept[i], tuple(rows[i]))
        assert s not in sigs, 'not minimal: %s %s' % (i, pol)
        sigs.add(s)
    # every retained state reaches acceptance; DENY behaves as sink
    for i in range(n):
        seen = set(); stack = [i]; ok = False
        while stack:
            s = stack.pop()
            if accept[s]: ok = True; break
            if s in seen: continue
            seen.add(s)
            for t in rows[s]:
                if t != D: stack.append(t)
        assert ok, 'dead state retained'
    # BFS numbering property
    number = {0: 0}; queue = [0]
    while queue:
        s = queue.pop(0)
        for c in range(len(order)):
            t = rows[s][c]
            if t == D: continue
            if t not in number:
                number[t] = len(number); queue.append(t)
    assert len(number) == n, 'unreachable row'
    for i in range(n):
        assert number[i] == i, 'numbering not breadth first'
    # behaviour over every sequence up to length 5
    for length in range(0, 6):
        for seq in itertools.product(order, repeat=length):
            want = allowed(rules, list(seq))
            got = image_run(image, columns, list(seq))
            assert want == got, 'mismatch %s %s want %s got %s' % (pol, seq, want, got)
    return pol, n, cells

def render(tree):
    kind = tree[0]
    if kind == 'atom':
        return '%s(%s)' % (tree[1], ','.join(tree[2]))
    if kind == 'n':
        return 'not(%s)' % render(tree[1])
    return '(%s %s %s)' % (render(tree[2]), tree[1], render(tree[3]))

bad = 0
for trial in range(400):
    k = rng.randint(1, 5)
    names = ['n%d' % i for i in range(k)]
    labels = rng.sample(range(1, 400), k)
    rules = rand_policy(names)
    try:
        pol, n, cells = check_image(rules, names, labels)
    except AssertionError as exc:
        bad += 1
        print('FAIL', exc)
        if bad > 4: break
print('property trials done, failures:', bad)
sys.exit(1 if bad else 0)
